INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_mah-pete101', 'stk-abdullah_mah', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f98481", "n": "Dr. Sidqi A. Abu-Khamsin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101 - term 171\n\nالتحضير : يعد الطلاب اذا العدد تمام خلاص مايحضر , اذا فيه واحد ناقص اما انه يجرد الطلاب او يقولون له الطلاب من غايب .\n\nطريقة الشرح : اسطووووووووورية , عندة سلايدات هو نفسه مسويها جدا جملية ومختصرة . اغلبيتها تكون صور وكلام بسيط , فلازم تكون حاضر المحاضرة عشان تعرف ايش صاير .\n\nالكويزات : قبل الكوز بيوم اواحيانا يومين , ينزل لنا ملف pdf فيه 20 سؤال راح يجيك 5 منها . بعض الاسئلة سهلة بعضها تقدر تطلعه من الانترنت وبعضا صعبة, اللي يركز معاه ويسجل نوتات معاه هو اللي راح يقدر يحل .\nعادة يجيب 3 اسئلة سهلة و 2 من اللي احسهم صعبين\n\nالمياجر : المادة مافيها مياجر\n\nالفاينلات : على نهاية الترم راح يصفى عندك 5 ملفات pdf بمجموع 100 سؤال تقريبا , الفاينل راح يكون من بين هذي الاسئلة . على فكرة ’ جميع الاسئلة written ومايقبل الاجوبة اللي كم كلمة بس .\n\nالقريد النهائي : ! A+\n\nالصوت : يزئر كالأسد و ينصت كالحكيم .\n\nاضافات: الدكتور عندة خبرة في الحياة الأكاديمية لفترة تمتد الى اكثر من 30 سنة ما شاء الله عليه , ف انت تتحدث عن رجل متبحر وفاهم في اللي قاعد يقوله .\nيعيب الدكتور انه يزعل اذا ماقلت له دكتور -_- , مرة واحد قال له teacher , رد عليه: لا قوللي ابله احسن هههههه .\nد. صدقي يفرح اذا تجيه اسئلة ذكية , ومبدع ف التحشير اذا جاته اسئلة غبية . نظرتة الاشمئزازية وحدها تكفي , واسئل مجرب ~_~ .\noverall : لا يفوتك .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485109-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sidqi-a-abu-khamsin/98481/13", "user": "Abdullah_MAH", "ts": 1514377381000, "tid": 98481, "pn": 13}}]}', 1514377381000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-husbkt-pete101', 'stk-husbkt', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f98485", "n": "Dr. Abdulaziz Al-Majed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101 - 181\n\nالتحضير : يحضر بداية الكلاس … طبعا م في الا سكشن واحد له … كل غياب عليه خصم 2%\nطريقة الشرح : يشرح من سلايداته … مملة بشكل عام … م احس في شيء شدني كلش … ممكن لأني بعد مب مهتم ف التخصص بشكل عام لأن تخصصي جيوفزكس\nالكويزات : أغلب الأسئلة تجي من سلايداته وبعضهم يجي من الكتاب … بالنسبة لنا حذف لنا أسوأ كوز … مشكلة كوزاته الاسئلة صعبة نسبيا كلا عدد… لكن في النهاية قام يسهل ممكن لأنه شاف الدرجات ضعيفة … بالعربي اذا صميت سلايداته امورك في السليم\nالمياجر: طبعا المادة م فيها مياجر فيها 6 كوزات كلهم ع 10% وفيها مختلف الأسئلة ( مب كومن )\nالفاينلات : عليه 20% وفي مختلف الأسئلة ( مب كومن )\nالقريد النهائي: B\nالصوت: ضعيف جدا يبي لك تصير قدام عشان تسمعه … يتكلم انجلش … الانجلش عنده عادي\nإضافات : الرجاال قمة في الأخلاق … التصحيح احسه مب عادل الى ذيك الدرجة ولكن لو صار عندك اعتراض ع درجتك رح له الأوفس … أخذت عنده B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504176-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulaziz-al-majed/98485/16", "user": "Husbkt", "ts": 1545991269000, "tid": 98485, "pn": 16}}]}', 1545991269000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fms1-pete101', 'stk-fms1', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f169385", "n": "Dr. Dhafer Abdullah Al-Shehri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101 T201\n\nالتحضير: كانت المحاضرات على مايكروسوفت تيمز و الدكتور مرات ينادي و مرات لا فا مافي طريقه محدده. والدكتور عرف اغلب اسامينا خاصه الي يفتحون الكام وقت المحاضره.\n\nالشرح: عن طريق سلايدات و فالعاده يجلس يسولف بالماده و الاشياء الي فيها و الحصه ممتعه ناخذ و نعطي مع الدكتور.\n\nالكويزات: اختبرنا 5 كوزات كانت سهله تجي من السلايدات و الكتاب. كان الي يسويها طالي ماجستير او دكتوراه نسيت. واذ صارت اي مشكله نكلمه و تتعدل.\n\nالفاينل: كان ملف ورد فيه 46 سوال تحله كان فيه رتن و اختر و توصيل و رترسم رسمه مبسطة كان سهل.\n\nالبروجكت: طلب منا نسوي ريسارش و برزينتيشن و يعين مجموعات عشوائي و العناوين بعد. اذ احتجت اي شي تقدر تكلمه او المساعد حقه.\n\nالدكتور هو التشيرمان فا كان مرات يجي مكانه طالب ماجستير/دكتوراه و يشرح عنه و هو نفسه الي يسوي الاختبارات لان الدكتور يكون منشغل. عموما اغلب دكاترة مادة PETE101 يكون ممتازين و الدكتور من الي شفته ممتاز و انصح فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527867-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dhafer-abdullah-al-shehri/169385/5", "user": "FMS1", "ts": 1610594067000, "tid": 169385, "pn": 5}}]}', 1610594067000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12081-pete101', 'stk-user12081', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f169385", "n": "Dr. Dhafer Abdullah Al-Shehri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101 T201\n\nالتحضير:\nايام يحضر بالكشف وايام يحمل الحضور من التيمز.\n\nالشرح:\nممتاز جداً. الدكتور له خبره كبيرة في حقول الـoffshore ويشارك خبرته مع الطلاب سواء من ناحية مهنية او من ناحية تعامل في الشركة.\n\nالكويزات:\nكويزات سهله من الكتاب والسلايدات المرفقة.\n\nالفاينل:\nملف وورد يسالك فيه عدة اسئلة. كان فيه اسئلة لازم تكتب الاجابات نصاُ. فيه كذلك خيارات وتوصيل. وطلب مننا نرسم نوع من انواع المكامن.\n\nالبروجيكت:\nوزعنا لمجموعات بشكل عشوائي بعدها وزع علينا مواضيع. تسوي ريبورت وسلايدات وبنهاية الترم يعطي كل مجموعة ربع ساعة يقدمون فيها عملهم.\n\nالقريد النهائي:\nA+\nغير ان الدكتور متمكن من التخصص , الدكتور وسيع صدر وياخذ ويعطي وباله طويل على الطلاب.\nمع اني مالي بالكورة ابداً لكنه كان يلطف جو المحاضرات بالحديث عن الدوري والمباريات القادمة… الخ\nانصح به وبشدة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529340-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dhafer-abdullah-al-shehri/169385/6", "user": "user12081", "ts": 1617549067000, "tid": 169385, "pn": 6}}]}', 1617549067000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed_s-pete101', 'stk-ahmed_s', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f172354", "n": "Dr. Sulaiman A. Alarifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 211\nمادة : PETE101\n\nالشرح : عنده سلايدات يمشي عليها والمواضيع من الكتاب ويزيد عليها معلومات اضافية او مواضيع ( يعني الشرح فري )\n\nالدكتور ماشاء الله عليه فاهم ويعرف يوصل المعلومة بشكل ممتاز وكلامه واضح\n\nالتصحيح: يعطيك حقك ويناقشك عادي في الدرجة. و حط في بالك انه مو عشان تناقشت معاه بيزيدك 😀\n\nالكويزات : من الكتاب فقط كل شابتر تقريبا ومحدد في مواعيده من بداية السمستر عشان لا يفاجئكم، اذا كان فيه ميجر او شيء وكلمتوه من بدري يتفهم ويأجله. الأسئلة فيها خيارات وتعاريف وأسئلة مقالية. اذا ذاكرت الكتاب زين بتكون سهلة اما اذا سحبت وبتدخل على الحدس بتلقم 👍\n\nالتحضير: نهاية كل كلاس يمشي على الاسماء، اذا شاف مافي غياب ما يحضر\n\nالقريد النهائي : A+\n\nاخر نقطة بضيفها انه بالنسبة لعمر الدكتور في القسم الا انه ما شاء الله عليه متمكن من التخصص وخبرته العلمية ممتازة وتحس انه قريب منك . يحب يتناقش ويستقبل الأسئلة بصدر رحب ولا يهاوش او شيء حتى مرة جلسنا ربع ساعة نسأل ويجاوب اللي يعرفه بدون ما يقاطع احد\n\nبداية الترم اعطانا هدية انواع من القهوة في علب صغيرة 😅 وجاب لنا بعدين عينات من النفط الثقيل والخفيف في علب محكمة الاغلاق وتناقشنا فيها، اخر السمستر جاب لنا القريدر حق المادة طلع يدرس ماستر وباحث عندنا في الكلية وتكلم عن شغله في المختبر وايش بحثه. وطالب سينيور تكلم لنا عن تجربته في التخصص وايش الصعوبات اللي ممكن نواجهها والمواد اللي نركز عليها والخطة الدراسية وغيرها…من الاخر هو وده يطلع طلاب فاهمين وممتازين من الناحية الاكاديمية والمهنية\n\nاخر نقطة واعتذر على الإطالة هي الترم بروجكت اعطانا مواضيع وقسمنا مجموعات وطلب تقرير وقدمنا برزنتيشن وناقشنا فيها ، قيمنا بشكل فردي على التقديم وبشكل جماعي على التقرير، طبعا عنده معايير يبغاها في التقرير امشوا عليها بالملي ولا بيخصم 😠\n\nبشكل عام دكاترة القسم ممتازين في هذي المادة ولا تتخوف من ناحية تنزل المادة عند مين اهم شي شد حيلك وربنا يوفقك 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533398-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sulaiman-a-alarifi/172354/4", "user": "Ahmed_S", "ts": 1641905485000, "tid": 172354, "pn": 4}}]}', 1641905485000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10962-pete101', 'stk-user10962', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f182529", "n": "Dr. Shirish Patil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101 -181\n\nالتحضير : ورقة تمر\nطريقة الشرح : يشرح على سلايداته و يحب يستخدم السبورة عشان يرسم أفكار الدرس أو يكتب الاختصارات مثل EOR - GOSP - …etc\nالكويزات : كانت أربع كويزات وعليها 60% ما أدري غير النظام أو لا.\nالمياجر: None\nالفاينلات : Tough\nالقريد النهائي : D\nالصوت: منخفض.\nإضافات : الدكتور طيب جدًا وشديد بالبرزنتيشن والريبورت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519092-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shirish-patil/182529/2", "user": "user10962", "ts": 1579069912000, "tid": 182529, "pn": 2}}]}', 1579069912000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11569-pete101', 'stk-user11569', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f182529", "n": "Dr. Shirish Patil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Pete 101 term 191\n\nالتحضير : ورقة تمر\nطريقة الشرح : يشرح سلايداته ويكتب على السبورة المسآئل المهمة الي بتجي بالاختبارات\nالكويزات : كانت صعبة لاني كنت اذاكر تسليك من الكتاب بس بعدين اكتشفنا انه يجيب كوزاته من ملفات الريسورس pete 201\nالمياجر:لايوجد\nالفاينلات : جب حاسبة معك\nالقريد النهائي: C\nالصوت: عالي\nإضافات :لا تخليه خيارك الاول إلا اذا بتكرف معاه من البداية اشوف د بوخمسين افضل من ناحية القريدات لكن كشرح وتأسيس أسسني زين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1520439-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shirish-patil/182529/3", "user": "user11569", "ts": 1583143306000, "tid": 182529, "pn": 3}}]}', 1583143306000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali224323-pete101', 'stk-ali224323', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f182529", "n": "Dr. Shirish Patil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101\nالتحضير : ,ورقة تمر ومتهاون في التحضير لو تجي متأخر مايقول شي\nطريقة الشرح : يشرح اشياء يمكن تفيدك مستقبلا لكن ماتستخدمها في الكورس , اهم شي ركز على المسائل , صحيح انها ماتجي في الكويزات لكنها بتجيك في الفاينل\nالكويزات :صعبة لكن الي درسوا عنده قبل قالوا لنا انه مايغير اسألته وبلقونها في الريسورسيس , الاسئلة كلها كتابة\nالمياجر:مافيه\nالفاينلات : صعب جدا لكنه وزع قريدات في الأخير\nالقريد النهائي: B\nالصوت:واضح\nإضافات :ركز على الكويزات لان عليها وزن كبير وهذا اكثر شي ضامنه\nلاتخليه خيارك الاول لان فيه احسن منه\nصحيح انه يكرف لكن يقول يبي الطلاب يتعودون لان بيكون الوضع كذا تلكورسات الجاية وفي الاخير القريدات كانت مرتفعه\nالبروجيكت لا تعطيه اهمية كبيرة وفي نفس الوقت لاتأجل فيه الى اخر شي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521811-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shirish-patil/182529/4", "user": "ALI224323", "ts": 1588762183000, "tid": 182529, "pn": 4}}]}', 1588762183000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12007-pete101', 'stk-user12007', 'PETE 101', 'doc', '{"docs": [{"id": "stk-dr-f182529", "n": "Dr. Shirish Patil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PETE 101 201 ترم كورونا\nالتحضير: غالبا عن طريق فورم التيمز لكن هو طول الترم ما وضح كيف فأتوقع انه سلك في هذا الامر\nالشرح: يقرا سلايداته ويشرحها بالتفصيل. شرحه حلو ودايم يجاوب على أسألتنا وما يمل منها\nالكويزات: 100% من الكتاب. مو هو اللي يحط الكويزات طالب دكتوراة مدري ماجيستير هو اللي يحطها. زي ما قلت لك 100% من الكتاب وما تطلع منه.\nميجر:-\nالفاينل: حول 45 سؤال. 100% من الكتاب وارجع لكوزاته قبل الفاينل\nالصوت: ممتازة انقليزيته\nالقريد النهائي: A+\nاضافات: اهم شي عنده البروجكت لأن يقول انت كطالب cpg بتسوي مثلها كثير فشد حيلك في البروجكت واذا عجبه البروجكت بدفك في الكوزات. الدكتور بصراحة حبيب لدرجة ما تتخيلها. دايم كنا نقوله نبي نأجل كوز اذا كان يعارض وقت مياجر مواد ثانية ويسمح لنا لكن للاسف اخذنا الدعوة سبهللة لين قال خلاص مافي تأجيل ههههههههه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527421-pete101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shirish-patil/182529/5", "user": "user12007", "ts": 1609405857000, "tid": 182529, "pn": 5}}]}', 1609405857000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
